import org.junit.Test;
import static org.junit.Assert.*;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

@RunWith(MockitoJUnitRunner.class)
public class PrettyPrintVisitorTest {

    @Mock
    private Printer printer;

    @Mock
    private CollectingPrinter collectingPrinter;

    public void setup() {
        when(printer.printLine(anyString())).thenReturn(collectingPrinter);
        when(printer.printLineWithColor(anyString(), anyString())).thenReturn(collectingPrinter);
        when(printer.printLineWithDelimiter(anyString())).thenReturn(collectingPrinter);
    }

    @Test
    public void visitAssignExprPrintsCorrectly() {
        setup();
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitAssignExpr(new AssingExpr("var", "x"));
        assertEquals("var x\n", collectingPrinter.toString());
    }

    @Test
    public void visitBinaryExprPrintsCorrectly() {
        setup();
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitBinaryExpr(new BinaryExpr("+", "x", 5));
        assertEquals("x + 5\n", collectingPrinter.toString());
    }

    @Test
    public void visitUnaryExprPrintsCorrectly() {
        setup();
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitUnaryExpr(new UnaryExpr("-", 5));
        assertEquals("-5\n", collectingPrinter.toString());
    }

    @Test
    public void visitConstExprPrintsCorrectly() {
        setup();
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitConstExpr(new Value(5));
        assertEquals("5\n", collectingPrinter.toString());
    }

    @Test
    public void visitFunctionCallExprPrintsCorrectly() {
        setup();
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitFunctionCallExpr(new FunctionCallExpr("add", "x", 5));
        assertEquals("add x 5\n", collectingPrinter.toString());
    }

