    public void visitVarExprPrintsCorrectly() {
        setup();
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        visitor.visitVarExpr(new VarExpr("x"));
        assertEquals("x\n", collectingPrinter.toString());
    }

